from pathlib import Path
import json
from datetime import datetime

# agent bus inbox recent unprocessed
state = Path.home() / 'Library/Application Support/youchu-agent-bus/state'
inbox = state / 'youchu_ai_inbox.jsonl'
processed_ids = set()
# common processed markers
for fname in ['processed_ids.json','processed.json','youchu_ai_processed.json']:
    p = state / fname
    if p.exists():
        try:
            data = json.loads(p.read_text())
            if isinstance(data, list):
                processed_ids.update(str(x) for x in data)
            elif isinstance(data, dict):
                processed_ids.update(str(k) for k in data.keys())
                if 'ids' in data: processed_ids.update(str(x) for x in data['ids'])
        except Exception as e:
            print('parse', fname, e)

sent_reply_to = set()
sent = state / 'sent.jsonl'
if sent.exists():
    for line in sent.read_text().splitlines()[-500:]:
        try:
            o = json.loads(line)
        except: continue
        for k in ('reply_to_bus_id','in_reply_to','reply_to'):
            if k in o and o[k] is not None:
                sent_reply_to.add(str(o[k]))
        text = str(o.get('text') or o.get('body') or '')
        if 'reply:bus:' in text:
            pass

print('processed_ids sample', list(processed_ids)[:5], 'count', len(processed_ids))
print('sent_reply_to count', len(sent_reply_to))

# list inbox last 30 and open-looking
if inbox.exists():
    lines = inbox.read_text().splitlines()
    print('inbox lines', len(lines))
    open_items = []
    for line in lines[-80:]:
        try:
            o = json.loads(line)
        except: continue
        bus_id = str(o.get('bus_id') or o.get('id') or o.get('message_id') or '')
        kind = o.get('kind') or o.get('type') or o.get('payload',{}).get('type') if isinstance(o.get('payload'), dict) else o.get('type')
        text = (o.get('text') or o.get('body') or o.get('prompt') or '')[:120]
        ts = o.get('ts') or o.get('created_at') or o.get('time')
        processed = bus_id in processed_ids or bus_id in sent_reply_to
        # also check flags
        if o.get('processed') or o.get('status') in ('processed','done','closed'):
            processed = True
        if not processed:
            open_items.append((ts, bus_id, kind, text))
    print('recent open-looking', len(open_items))
    for it in open_items[-15:]:
        print(it)

# list state files
print('--- state files ---')
for p in sorted(state.iterdir()):
    print(p.name, p.stat().st_size)
